/// The roles as a Material 3 colour scheme. Material draws primary, secondary, tertiary and error
/// as text and icons on surfaces, so they take the derived text colours (4.5:1 on every surface);
/// the brand fills, which meet their targets with their on-fill colour, are the containers.
ColorScheme ndColorScheme(NDColors c, {required bool dark}) => ColorScheme(
      brightness: dark ? Brightness.dark : Brightness.light,
      primary: c.accentText,
      onPrimary: c.surfaceBase,
      primaryContainer: c.accentFill,
      onPrimaryContainer: c.accentOnFill,
      inversePrimary: c.textInverse,
      secondary: c.accentText,
      onSecondary: c.surfaceBase,
      secondaryContainer: c.accentSubtle,
      onSecondaryContainer: c.textPrimary,
      tertiary: c.accentText,
      onTertiary: c.surfaceBase,
      tertiaryContainer: c.accentSubtle,
      onTertiaryContainer: c.textPrimary,
      error: c.statusDangerText,
      onError: c.surfaceBase,
      errorContainer: c.statusDangerSubtle,
      onErrorContainer: c.textPrimary,
      surface: c.surfaceBase,
      onSurface: c.textPrimary,
      onSurfaceVariant: c.textSecondary,
      surfaceDim: c.surfaceSunken,
      surfaceBright: c.surfaceRaised,
      surfaceContainerLowest: c.surfaceSunken,
      surfaceContainerLow: c.surfaceBase,
      surfaceContainer: c.surfaceRaised,
      surfaceContainerHigh: c.surfaceRaised,
      surfaceContainerHighest: c.surfaceOverlay,
      surfaceTint: Colors.transparent,
      inverseSurface: c.surfaceInverse,
      onInverseSurface: c.textInverse,
      outline: c.borderControl,
      outlineVariant: c.borderSubtle,
      shadow: const Color(0xFF000000),
      scrim: c.overlayScrim,
    );

/// The kit's styles as Material 3 typography; each Material role takes the kit style that names it.
TextTheme ndTextTheme(NDPlatform platform, [NDScript script = NDScript.latin]) {
  TextStyle style(NDTypeRole role) => NDTextStyle.resolve(role, platform, script).toTextStyle(platform);
  return TextTheme(
    displaySmall: style(NDTypeRole.display),
    headlineLarge: style(NDTypeRole.h1),
    headlineMedium: style(NDTypeRole.h2),
    headlineSmall: style(NDTypeRole.h3),
    titleLarge: style(NDTypeRole.h4),
    bodyLarge: style(NDTypeRole.lead),
    bodyMedium: style(NDTypeRole.body),
    labelLarge: style(NDTypeRole.label),
    bodySmall: style(NDTypeRole.caption),
  );
}

/// A corner of [radius] logical pixels; the pill radius becomes a stadium.
OutlinedBorder _ndCorner(double radius) => radius >= 9999
    ? const StadiumBorder()
    : RoundedRectangleBorder(borderRadius: BorderRadius.circular(radius));

/// Material 3 ThemeData in NDDev colours, type and component shapes, with the colour and metric
/// extensions.
ThemeData ndThemeData({
  required NDTheme theme,
  required NDDirection direction,
  NDPlatform platform = NDPlatform.android,
  NDDensity density = NDDensity.comfortable,
  NDScript script = NDScript.latin,
}) {
  final colors = NDColors.resolve(theme, direction);
  final metrics = NDMetrics.resolve(platform, density);
  final scheme = ndColorScheme(colors, dark: theme.isDark);
  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    scaffoldBackgroundColor: colors.surfaceBase,
    textTheme: ndTextTheme(platform, script).apply(
      bodyColor: colors.textPrimary,
      displayColor: colors.textPrimary,
    ),
    visualDensity: density == NDDensity.compact ? VisualDensity.compact : VisualDensity.standard,
    materialTapTargetSize: MaterialTapTargetSize.padded,
    focusColor: colors.focusRing,
    // Material's component shapes in the kit's radii (the pill radius becomes a stadium).
    cardTheme: CardThemeData(shape: _ndCorner(metrics.cardRadius)),
    dialogTheme: DialogThemeData(shape: _ndCorner(metrics.dialogRadius)),
    bottomSheetTheme: BottomSheetThemeData(
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(metrics.dialogRadius)),
      ),
    ),
    popupMenuTheme: PopupMenuThemeData(shape: _ndCorner(metrics.menuRadius)),
    chipTheme: ChipThemeData(shape: _ndCorner(metrics.chipRadius)),
    extensions: [NDColorsExtension(colors), NDMetricsExtension(metrics)],
  );
}

extension NDThemeContext on BuildContext {
  /// The NDDev colours of the nearest theme.
  NDColors get ndColors =>
      Theme.of(this).extension<NDColorsExtension>()?.colors ??
      NDColors.resolve(NDTheme.light, NDDirection.on);

  /// The NDDev metrics of the nearest theme.
  NDMetrics get ndMetrics =>
      Theme.of(this).extension<NDMetricsExtension>()?.metrics ??
      NDMetrics.resolve(NDPlatform.android, NDDensity.comfortable);
}
